import asyncio
import types
import typing
from argparse import (
    ArgumentParser,
    ArgumentDefaultsHelpFormatter,
    BooleanOptionalAction,
    Namespace,
)
from pathlib import Path


class FnToCLI:
    """
    A utility class which automatically infers and generates ArgParse command
    line options from a function based on defaults/type annotations

    This is _very_ basic; supports:
    * Args of int, str, float types (same logic as default argparse)
    * Args of Path type (converts CLI string to Path object)
    * Args of bool type (Uses argparse BooleanOptionalAction)
        * eg `do_blah=False` becomes `--do-blah, --no-do-blah`
    * Args of list[T] where T is int, str, float, or Path
        * Required list args are positional (nargs='+')
        * Optional list args use --flag syntax (nargs='*')
    * Args of typing.Optional (or anything with a default)
    * Args of typing.Literal (uses argparse choices)
        * eg `color: Literal['red, 'black']` becomes `--color red|black` (with docs)
    * Type deduction of default values
    * Supports async functions automatically
    * Includes docstring if it's in `:param my_arg: Description of my arg` format

    Anything else will likely error :)

    Example:
    if __name__ == '__main__':
        FnToCLI(my_func).run()
    """

    def __init__(self, fn: typing.Callable):
        self.fn = fn
        arg_names = fn.__code__.co_varnames[: fn.__code__.co_argcount]
        annotations = typing.get_type_hints(fn)
        defaults: list = fn.__defaults__ or []  # type: ignore[assignment]
        num_required = len(arg_names) - len(defaults)
        default_args = arg_names[num_required:]
        defaults: dict = {  # type: ignore[no-redef]
            arg: default for [arg, default] in zip(default_args, defaults)
        }

        docs = fn.__doc__ or ''
        arg_docs = self.parse_docs(docs)
        self.parser = ArgumentParser(
            description=docs.split(':param', 1)[0],
            formatter_class=ArgumentDefaultsHelpFormatter,
        )
        self.args: Namespace | None = None
        for arg in arg_names:
            optional = arg in defaults
            cli_name = arg.replace('_', '-')

            if arg in annotations:
                arg_opts = self.type_to_argparse(annotations[arg])
            elif arg in defaults:
                arg_opts = self.type_to_argparse(type(defaults[arg]))  # type: ignore[call-overload]
            else:
                raise ValueError(f'{arg} has no type information')

            # Help needs to always be defined, or it won't show the default :/
            arg_opts['help'] = arg_docs.get(arg) or '-'

            if optional:
                opt_name = f'--{cli_name}' if len(cli_name) > 1 else f'-{cli_name}'
                # For list types used as optional flags, use nargs='*' so that
                # not providing the flag yields the default (e.g., None), while
                # providing --flag with values yields a list.
                if arg_opts.get('nargs') == '+':
                    arg_opts = {**arg_opts, 'nargs': '*'}
                self.parser.add_argument(opt_name, default=defaults[arg], **arg_opts)  # type: ignore[call-overload]
            else:
                self.parser.add_argument(cli_name, **arg_opts)

    def parse_args(self, args: 'typing.Sequence[str] | None' = None):
        self.args = self.parser.parse_args(args)
        return self.args

    def args_dict(self):
        if not self.args:
            self.parse_args()

        return {k.replace('-', '_'): v for k, v in self.args.__dict__.items()}

    def run(self):
        args_dicts = self.args_dict()
        if asyncio.iscoroutinefunction(self.fn):
            return asyncio.run(self.fn(**args_dicts))
        else:
            return self.fn(**args_dicts)

    @staticmethod
    def parse_docs(docs):
        params = docs.strip().split(':param ')[1:]
        params = [p.strip() for p in params]
        params = [p.split(':', 1) for p in params if p]
        return {name: docs.strip() for [name, docs] in params}

    @staticmethod
    def type_to_argparse(typ: type) -> dict:
        if FnToCLI.is_optional(typ):
            return FnToCLI.type_to_argparse(
                next(t for t in typing.get_args(typ) if not isinstance(t, type(None)))
            )
        if typ == bool:
            return {'type': typ, 'action': BooleanOptionalAction}
        if typ in (int, str, float, Path):
            return {'type': typ}
        if typing.get_origin(typ) == list:
            inner_args = typing.get_args(typ)
            if inner_args and inner_args[0] in (int, str, float, Path):
                return {'type': inner_args[0], 'nargs': '+'}
        if typing.get_origin(typ) == typing.Literal:
            return {'choices': typing.get_args(typ)}
        raise ValueError(f'Unsupported type: {typ}')

    @staticmethod
    def is_optional(typ: type) -> bool:
        return (
            (typing.get_origin(typ) is typing.Union or isinstance(typ, types.UnionType))
            and type(None) in typing.get_args(typ)
            and len(typing.get_args(typ)) == 2
        )

import asyncio
from argparse import BooleanOptionalAction
from pathlib import Path
import typing
from scripts.solr_builder.solr_builder.fn_to_cli import FnToCLI


class TestFnToCLI:
    def test_full_flow(self):
        def fn(works: list[str], solr_url: str | None = None):
            """
            Do some magic!
            :param works: These are works
            :param solr_url: This is solr url
            """

        cli = FnToCLI(fn)
        assert cli.parser.description.strip() == 'Do some magic!'
        assert '--solr-url' in cli.parser.format_usage()

    def test_parse_docs(self):
        docs = """
        :param a: A
        :param b: B
        :param c: C
        """
        assert FnToCLI.parse_docs(docs) == {'a': 'A', 'b': 'B', 'c': 'C'}

        docs = """
        Some function description

        :param a: A asdfas
        """
        assert FnToCLI.parse_docs(docs) == {'a': 'A asdfas'}

    def test_type_to_argparse(self):
        assert FnToCLI.type_to_argparse(int) == {'type': int}
        assert FnToCLI.type_to_argparse(typing.Optional[int]) == {  # noqa: UP007
            'type': int
        }
        assert FnToCLI.type_to_argparse(bool) == {
            'type': bool,
            'action': BooleanOptionalAction,
        }
        assert FnToCLI.type_to_argparse(typing.Literal['a', 'b']) == {
            'choices': ('a', 'b'),
        }

    def test_is_optional(self):
        assert FnToCLI.is_optional(typing.Optional[int])  # noqa: UP007
        assert not FnToCLI.is_optional(int)

    # --- New tests for Path support ---

    def test_type_to_argparse_path(self):
        assert FnToCLI.type_to_argparse(Path) == {'type': Path}

    def test_type_to_argparse_optional_path(self):
        assert FnToCLI.type_to_argparse(Path | None) == {'type': Path}

    def test_path_argument_parsed(self):
        def fn(output: Path):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['some/path'])
        assert args.output == Path('some/path')

    def test_optional_path_argument_parsed(self):
        def fn(output: Path | None = None):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['--output', 'some/path'])
        assert args.output == Path('some/path')

    def test_optional_path_argument_defaults_none(self):
        def fn(output: Path | None = None):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args([])
        assert args.output is None

    # --- New tests for list support ---

    def test_type_to_argparse_list_int(self):
        assert FnToCLI.type_to_argparse(list[int]) == {'type': int, 'nargs': '+'}

    def test_type_to_argparse_list_str(self):
        assert FnToCLI.type_to_argparse(list[str]) == {'type': str, 'nargs': '+'}

    def test_type_to_argparse_list_float(self):
        assert FnToCLI.type_to_argparse(list[float]) == {'type': float, 'nargs': '+'}

    def test_type_to_argparse_list_path(self):
        assert FnToCLI.type_to_argparse(list[Path]) == {'type': Path, 'nargs': '+'}

    def test_required_list_int_positional(self):
        """Required list parameters are positional; values are converted to the element type."""

        def fn(counts: list[int]):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['1', '2', '3'])
        assert args.counts == [1, 2, 3]

    def test_required_list_path_positional(self):
        """Required list[Path] parameters are positional; strings are converted to Path."""

        def fn(files: list[Path]):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['/a/b', '/c/d'])
        assert args.files == [Path('/a/b'), Path('/c/d')]

    def test_optional_list_path_via_flag(self):
        """Optional list[Path] parameters are supplied via --<name> flag."""

        def fn(files: list[Path] | None = None):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['--files', '/a/b', '/c/d'])
        assert args.files == [Path('/a/b'), Path('/c/d')]

    def test_optional_list_path_defaults_none(self):
        """Omitting an optional list[Path] parameter results in None."""

        def fn(files: list[Path] | None = None):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args([])
        assert args.files is None

    def test_optional_list_int_via_flag(self):
        """Optional list[int] parameters are supplied via --<name> flag."""

        def fn(counts: list[int] | None = None):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['--counts', '10', '20', '30'])
        assert args.counts == [10, 20, 30]

    # --- New tests for parse_args with explicit args ---

    def test_parse_args_accepts_sequence(self):
        """parse_args should accept an explicit list of argument strings."""

        def fn(value: int):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['42'])
        assert args.value == 42

    def test_parse_args_none_uses_sys_argv(self):
        """parse_args(None) falls through to sys.argv (argparse default)."""

        def fn(value: int = 0):
            pass

        cli = FnToCLI(fn)
        # Passing an empty list simulates no extra argv; default should apply.
        args = cli.parse_args([])
        assert args.value == 0

    # --- New tests for run returning function result ---

    def test_run_returns_result(self):
        """run() should return the result of the wrapped function."""

        def fn(x: int, y: int = 0):
            return x + y

        cli = FnToCLI(fn)
        cli.parse_args(['3', '--y', '4'])
        result = cli.run()
        assert result == 7

    def test_run_returns_result_async(self):
        """run() should return the result of an async wrapped function."""

        async def fn(x: int, y: int = 0):
            return x + y

        cli = FnToCLI(fn)
        cli.parse_args(['5', '--y', '2'])
        result = cli.run()
        assert result == 7

    # --- CLI option name mapping ---

    def test_cli_option_name_maps_to_param_name(self):
        """--files on the CLI populates the `files` parameter."""

        def fn(files: list[Path] | None = None):
            pass

        cli = FnToCLI(fn)
        args = cli.parse_args(['--files', 'a.txt', 'b.txt'])
        # The namespace attribute should be 'files' (underscores, not hyphens)
        assert hasattr(args, 'files')
        assert args.files == [Path('a.txt'), Path('b.txt')]

    def test_cli_option_underscore_to_hyphen(self):
        """A parameter named my_output maps to --my-output on the CLI."""

        def fn(my_output: Path | None = None):
            pass

        cli = FnToCLI(fn)
        assert '--my-output' in cli.parser.format_usage()
        args = cli.parse_args(['--my-output', 'out.txt'])
        # args_dict converts hyphens back to underscores for the function call
        d = cli.args_dict()
        assert d['my_output'] == Path('out.txt')

